#!/bin/bash
# Issue 47 P1/P2: build a WCT worktree (SL7 container, cvmfs e26 deps, the same configure as the #43 builds).
#   build.sh <src> <prefix> configure|install|doctest [targets]
# Runs inside: /exp/sbnd/app/users/yuhw/claude-utilities/in-gpvm-sl7.sh bash -c '...'
#   test branch: src /exp/sbnd/data/users/yuhw/wct-aur-test   prefix /exp/sbnd/data/users/yuhw/opt-aur-test
#   master:      src /exp/sbnd/data/users/yuhw/wct-master-p2  prefix /exp/sbnd/data/users/yuhw/opt-master-p2 (doctests only)
SRC=${1:?src}; PREFIX=${2:?prefix}; MODE=${3:?mode}; J=${J:-32}
source /exp/sbnd/app/users/yuhw/wcp-porting-img/sbnd/setup-local-opt.sh >/dev/null 2>&1
cd $SRC || exit 1
export CXXFLAGS=-DSPDLOG_FMT_EXTERNAL
case $MODE in
  configure) ./wcb configure --prefix=$PREFIX '--build-debug=-O3 -g -fno-omit-frame-pointer' --with-tbb=/cvmfs/larsoft.opensciencegrid.org/products/tbb/v2021_9_0/Linux64bit+3.10-2.17-e26 --with-jsoncpp=/cvmfs/larsoft.opensciencegrid.org/products/jsoncpp/v1_9_5a/Linux64bit+3.10-2.17-e26-prof --with-jsonnet-include=/cvmfs/larsoft.opensciencegrid.org/products/gojsonnet/v0_18_0/Linux64bit+3.10-2.17-e26/include --with-jsonnet-lib=/cvmfs/larsoft.opensciencegrid.org/products/gojsonnet/v0_18_0/Linux64bit+3.10-2.17-e26/lib --with-eigen-include=/cvmfs/larsoft.opensciencegrid.org/products/eigen/v23_08_01_66e8f/include/eigen3/ --with-root=/cvmfs/larsoft.opensciencegrid.org/products/root/v6_28_12/Linux64bit+3.10-2.17-e26-p3915-prof --with-fftw=/cvmfs/larsoft.opensciencegrid.org/products/fftw/v3_3_10/Linux64bit+3.10-2.17 --with-fftw-include=/cvmfs/larsoft.opensciencegrid.org/products/fftw/v3_3_10/Linux64bit+3.10-2.17/include --with-fftw-lib=/cvmfs/larsoft.opensciencegrid.org/products/fftw/v3_3_10/Linux64bit+3.10-2.17/lib --with-fftwthreads=/cvmfs/larsoft.opensciencegrid.org/products/fftw/v3_3_10/Linux64bit+3.10-2.17 --boost-includes=/cvmfs/larsoft.opensciencegrid.org/products/boost/v1_82_0/Linux64bit+3.10-2.17-e26-prof/include --boost-libs=/cvmfs/larsoft.opensciencegrid.org/products/boost/v1_82_0/Linux64bit+3.10-2.17-e26-prof/lib --boost-mt --with-hdf5=/cvmfs/larsoft.opensciencegrid.org/products/hdf5/v1_12_2a/Linux64bit+3.10-2.17-e26-prof --with-spdlog-include=/cvmfs/larsoft.opensciencegrid.org/products/spdlog/v1_14_1/Linux64bit+3.10-2.17-e26-prof/include,/cvmfs/larsoft.opensciencegrid.org/products/fmt/v11_0_2/Linux64bit+3.10-2.17-e26-prof/include --with-spdlog-lib=/cvmfs/larsoft.opensciencegrid.org/products/spdlog/v1_14_1/Linux64bit+3.10-2.17-e26-prof/lib64,/cvmfs/larsoft.opensciencegrid.org/products/fmt/v11_0_2/Linux64bit+3.10-2.17-e26-prof/lib64 --with-spdlog-libs=spdlog,fmt --with-protobuf-include=/cvmfs/larsoft.opensciencegrid.org/products/protobuf/v3_21_12a/Linux64bit+3.10-2.17-e26/include/ --with-protobuf-lib=/cvmfs/larsoft.opensciencegrid.org/products/protobuf/v3_21_12a/Linux64bit+3.10-2.17-e26/lib --with-grpc=/cvmfs/larsoft.opensciencegrid.org/products/grpc/v1_35_0c/Linux64bit+3.10-2.17-e26 --with-grpc-include=/cvmfs/larsoft.opensciencegrid.org/products/grpc/v1_35_0c/Linux64bit+3.10-2.17-e26/include --with-grpc-lib=/cvmfs/larsoft.opensciencegrid.org/products/grpc/v1_35_0c/Linux64bit+3.10-2.17-e26/lib --with-triton-include=/cvmfs/larsoft.opensciencegrid.org/products/triton/v2_25_0d/Linux64bit+3.10-2.17-e26/include --with-triton-lib=/cvmfs/larsoft.opensciencegrid.org/products/triton/v2_25_0d/Linux64bit+3.10-2.17-e26/lib --with-libtorch=/cvmfs/larsoft.opensciencegrid.org/products/libtorch/v2_1_1b/Linux64bit+3.10-2.17-e26/ --with-libtorch-include=/cvmfs/larsoft.opensciencegrid.org/products/libtorch/v2_1_1b/Linux64bit+3.10-2.17-e26/include,/cvmfs/larsoft.opensciencegrid.org/products/libtorch/v2_1_1b/Linux64bit+3.10-2.17-e26/include/torch/csrc/api/include --with-libtorch-libs torch,torch_cpu,c10 ;;
  install) ./wcb -j$J --notests install ;;
  doctest) ./wcb -j$J --tests --targets=${4:-wcdoctest-clus,wcdoctest-pyutil} ;;
  *) echo "mode?"; exit 2 ;;
esac
